  @keyframes phonk-impact-shake {
    0%   { transform: scale(1.14) translate(0, 0) rotate(0deg); filter: brightness(2.2) contrast(1.5) drop-shadow(-10px 0 0 rgba(255,0,60,0.85)) drop-shadow(10px 0 0 rgba(0,240,255,0.85)); }
    25%  { transform: scale(1.08) translate(-10px, 8px) rotate(-1.2deg); }
    50%  { transform: scale(1.04) translate(8px, -6px) rotate(1.2deg); filter: brightness(1.3) contrast(1.2) drop-shadow(-4px 0 0 rgba(255,0,60,0.5)) drop-shadow(4px 0 0 rgba(0,240,255,0.5)); }
    75%  { transform: scale(1.02) translate(-4px, 3px) rotate(-0.5deg); }
    100% { transform: scale(1.00) translate(0, 0) rotate(0deg); filter: brightness(1) contrast(1) drop-shadow(0 0 0 transparent); }
